use super::{hotkeys::Chord,errors::{DiscordError,Result},detection};
use windows::Win32::{UI::{Input::KeyboardAndMouse::*,WindowsAndMessaging::{GetForegroundWindow,GetWindowThreadProcessId}},System::Threading::GetCurrentProcessId};
fn events(chord:&Chord)->Vec<(u16,bool)>{let keys=[0xA2,0xA4,0xA0,chord.key];keys.iter().map(|k|(*k,false)).chain(keys.iter().rev().map(|k|(*k,true))).collect()}
fn outstanding(events:&[(u16,bool)],sent:usize)->Vec<u16>{let mut pressed=vec![];for(key,up)in events.iter().take(sent){if *up{pressed.retain(|k|k!=key);}else{pressed.push(*key);}}pressed.reverse();pressed}
fn input(key:u16,up:bool)->INPUT{let scan=unsafe{MapVirtualKeyW(key as u32,MAPVK_VK_TO_VSC)}as u16;INPUT{r#type:INPUT_KEYBOARD,Anonymous:INPUT_0{ki:KEYBDINPUT{wScan:scan,dwFlags:KEYEVENTF_SCANCODE|if up{KEYEVENTF_KEYUP}else{KEYBD_EVENT_FLAGS(0)},..Default::default()}}}}
pub fn send(chord:&Chord)->Result<()> {unsafe{
 for key in [0x10,0x11,0x12,0x5B,0x5C,0xA0,0xA1,0xA2,0xA3,0xA4,0xA5,chord.key]{if GetAsyncKeyState(key as i32)<0{return Err(DiscordError::new("keys_held","Отпустите Ctrl, Alt, Shift, Win и функциональную клавишу, затем повторите действие."));}}
 let mut foreground=0;GetWindowThreadProcessId(GetForegroundWindow(),Some(&mut foreground));let own=detection::integrity(GetCurrentProcessId());if foreground==0||!own.zip(detection::integrity(foreground)).is_some_and(|(a,b)|b<=a){return Err(DiscordError::new("uipi","Уровень доступа активного окна не позволяет безопасно отправить сочетание. Переключитесь в обычное окно; повышение прав не требуется."));}
 let plan=events(chord);let inputs:Vec<_>=plan.iter().map(|(k,up)|input(*k,*up)).collect();let sent=SendInput(&inputs,std::mem::size_of::<INPUT>()as i32)as usize;
 if sent!=inputs.len(){let release:Vec<_>=outstanding(&plan,sent).into_iter().map(|k|input(k,true)).collect();if !release.is_empty(){let released=SendInput(&release,std::mem::size_of::<INPUT>()as i32)as usize;if released<release.len(){let _=SendInput(&release[released..],std::mem::size_of::<INPUT>()as i32);}}return Err(DiscordError::new("input_incomplete","Сочетание не отправлено полностью. Выполнена попытка отпускания введённых клавиш. Windows/UIPI может блокировать ввод; состояние Discord неизвестно."));}Ok(())
}}
#[cfg(test)]mod tests{use super::*;#[test]fn every_partial_prefix_releases_only_injected_keys(){let plan=events(&Chord{canonical:String::new(),key:0x78});for n in 0..=8{let release=outstanding(&plan,n);let mut held=std::collections::HashSet::new();for(k,up)in plan.iter().take(n){if *up{held.remove(k);}else{held.insert(*k);}}assert_eq!(release.len(),held.len());assert!(release.iter().all(|k|held.contains(k)));}assert!(outstanding(&plan,8).is_empty());}}
